// TH18 v1.00a st02mbs::MBoss / MBoss1, source lines 6-175; stage entry st02.ecl:1718.
// Source t0 = real MBoss script start. The control enemy owns the phase and holds the
// 120-frame opening buffer; the real boss is created at the source entry position.
const TIME_LIMIT: int = 1740;    // 120 buffer + source timeout 1500 + 120 tail
const SOURCE_LIMIT: int = 1500;  // source 27: setInterrupt(1,0,1500,...), timeout 28
const TH18_RICE: int = 480;      // source type 8
const TH18_BIG_BALL2: int = 656; // source type 19

// Source 118-120: ANIM omitted; OFFSCREEN a=200; ANGLE_ACCEL a=200,
// speed += 0.02/tick, angle += C/tick (C=182 BAM E/N/L, 200 BAM H).
xformdef SPIRAL_ACCEL(omega: angle) {
    offscreen_keep(200);
    set_ang_vel(omega);
    set_accel(0.02fx);
    wait(200);
    set_ang_vel(0bam);
    set_accel(0fx);
}

// Source 160-171: VELTIME a=60, r=0.8/0.8/1.0/1.4, s sentinel keeps the direction.
xformdef DECEL_TO_60(target: fx) {
    set_accel((target - 3fx) / 60fx);
    wait(60);
    set_accel(0fx);
}

// Source 100-132: etAim(0,1) fixed fan, etCount rank 10/10/10/16, one speed layer
// 1.5, 20deg spacing, base swept by -step each of D=10/20/26/32 volleys, wait(9).
// ANIM a=1 birth backstep 4*1.5px is kept through sh_dist.  Point set equals the
// source's alternating fan; target creation order sweeps from one side.
sub fan_volleys(base: angle, step: angle, shots: int, ways: int, omega: angle) {
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 10);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, -6fx);
    sh_xform(0, SPIRAL_ACCEL(omega));
    var a: angle = base;
    for i in 0..shots {
        if $frame >= self_int(1) { return; }
        sh_angle(0, a, 3641 as angle); // source 0.34906584 rad
        a = a - step;
        sh_fire(0);
        wait(9);
    }
}

// Source 135-173: async MBoss1_at2 -> MBoss1_at2b.  Ring mode2 aimed at the player,
// 32 ways, one speed layer 3.0, sprite type 19 color 3, then VELTIME.
// Source calls: all ranks once; H and L add two; L adds two more.
async sub ring_helper(rank: int) {
    var target: fx = 0.8fx;
    if rank == 2 { target = 1.0fx; }
    if rank == 3 { target = 1.4fx; }
    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL2, 3);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 32, 1);
    sh_speed(0, 3fx, 0fx);
    sh_angle(0, 0deg, 0deg);
    sh_dist(0, -12fx); // ANIM a=1 birth backstep 4*3px
    sh_xform(0, DECEL_TO_60(target));
    if $frame >= self_int(1) { return; }
    sh_fire(0);
    if rank >= 2 {
        wait(40);
        if $frame >= self_int(1) { return; }
        sh_fire(0);
        wait(40);
        if $frame >= self_int(1) { return; }
        sh_fire(0);
    }
    if rank >= 3 {
        wait(40);
        if $frame >= self_int(1) { return; }
        sh_fire(0);
        wait(40);
        if $frame >= self_int(1) { return; }
        sh_fire(0);
    }
}

// Source moveRand(60,4,0.7) with moveLimit(0,128,160,256):
// step k speed 0.7*(1-k/60), direction sampled once per call, per-frame limits
// x in [-80,80], y in [0,256], inner direction zone x+-40, y 64..192.
sub move_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0)*speed;
    var ny: fx = $self_y + self_fx(1)*speed;
    if nx < -80fx { nx = -80fx; }
    if nx > 80fx { nx = 80fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub move_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    move_step();
}
sub move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -40fx {
        a = r/3;
    } else if $self_x > 40fx {
        a = r/3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    move_begin(a as angle);
}
// Advances the per-frame moveRand motion while the source ECL waits.
sub timed_wait(frames: int) {
    for i in 0..frames {
        if $frame >= self_int(1) { return; }
        wait(1);
        move_step();
    }
}

// Source 6-98: boss init, entry move to (0,128) over 100 frames (mode 4 = QUAD_OUT),
// wait 40, wait 80, then endless MBoss1 loop until the slot-1 timeout at 1500.
async sub mboss_main() {
    set_invuln(65535);
    set_hurtbox(24fx); // source 48/48
    set_hitbox(20fx);  // source 40/40
    set_self_int(1, $frame + SOURCE_LIMIT);
    move_to(0, -192fx, -64fx, EASE_LINEAR); // source 30 movePos
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT); // source 31
    wait(40);
    // Source 33 moveLimit has no standing target verb; it is applied per tick below.
    wait(80);
    var rank: int = global(GVAR_RANK);
    var ways: int = 10;
    if rank == 3 { ways = 16; }
    var shots: int = 10;
    if rank == 1 { shots = 20; }
    if rank == 2 { shots = 26; }
    if rank == 3 { shots = 32; }
    var omega: angle = 182 as angle;
    if rank == 2 { omega = 200 as angle; }
    var gap: int = 120;
    if rank == 2 { gap = 90; }
    if rank == 3 { gap = 60; }
    loop {
        if $frame >= self_int(1) { return; }
        spawn ring_helper(rank);
        fan_volleys(-16384 as angle, 4005 as angle, shots, ways, omega);
        if $frame >= self_int(1) { return; }
        move_rand();
        timed_wait(gap);
        if $frame >= self_int(1) { return; }
        spawn ring_helper(rank);
        fan_volleys(-16384 as angle, -4005 as angle, shots, ways, -omega);
        if $frame >= self_int(1) { return; }
        move_rand();
        timed_wait(gap);
    }
}

// Control enemy at (0,0): phase owner, no body collision, 120-frame buffer.
async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, none, TIME_LIMIT, 0);
    wait(120);
    _ = spawn_enemy(-192fx, -32fx, 1000, 0, 0, 0, mboss_main); // source 1718
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
